const { chromium } = require('playwright');
const fs = require('fs');
const path = require('path');

(async () => {
  const html = fs.readFileSync('index.html', 'utf8');
  const css  = fs.readFileSync('style.css',  'utf8');
  const js   = fs.readFileSync('main.js',    'utf8');

  // Inline CSS and JS so Playwright file:// can load everything
  const inlined = html
    .replace('<link rel="stylesheet" href="style.css" />', `<style>${css}</style>`)
    .replace('<script src="main.js"></script>', `<script>${js}</script>`);

  const tmpFile = '/tmp/test-page.html';
  fs.writeFileSync(tmpFile, inlined);

  const b = await chromium.launch();
  const page = await b.newPage();
  await page.goto('file://' + tmpFile, { waitUntil: 'load' });
  await page.addScriptTag({ path: '/tmp/axe.min.js' });
